#!/usr/bin/env python3
from pathlib import Path

index = Path('index.html')
source = index.read_text(encoding='utf-8')

old_registry = """const VERIFIED_MANUAL_PROMO_IDENTITIES = {\n  'MEP 091':{\n    name:'Mega Dragonite ex',localId:'091',setId:'mep',setName:'Promozioni MEP',finish:'Holo',\n    source:'Pokémon ufficiale · MEP 091; finitura Holo verificata da catalogo promo indipendente',\n    sourceUrl:'https://www.pokemon.com/it/play-pokemon/info/entrata-in-vigore-delle-carte-promozionali-del-gcc-pokemon',\n    verified:'2026-09-11'\n  }\n};\n"""

new_registry = """const VERIFIED_MANUAL_PROMO_IDENTITIES = {\n  'MEP 089':{name:'Mega Zeraora ex',localId:'089',setId:'mep',setName:'Promozioni MEP',category:'Pokemon',finish:'Holo',source:'Pokémon ufficiale · MEP 089; Mega Forces Tin foil promo',sourceUrl:'https://www.pokemon.com/it/play-pokemon/info/entrata-in-vigore-delle-carte-promozionali-del-gcc-pokemon',verified:'2026-09-11'},\n  'MEP 090':{name:'Mega Darkrai ex',localId:'090',setId:'mep',setName:'Promozioni MEP',category:'Pokemon',finish:'Holo',source:'Pokémon ufficiale · MEP 090; Mega Forces Tin foil promo',sourceUrl:'https://www.pokemon.com/it/play-pokemon/info/entrata-in-vigore-delle-carte-promozionali-del-gcc-pokemon',verified:'2026-09-11'},\n  'MEP 091':{\n    name:'Mega Dragonite ex',localId:'091',setId:'mep',setName:'Promozioni MEP',category:'Pokemon',finish:'Holo',\n    source:'Pokémon ufficiale · MEP 091; Mega Forces Tin foil promo',\n    sourceUrl:'https://www.pokemon.com/it/play-pokemon/info/entrata-in-vigore-delle-carte-promozionali-del-gcc-pokemon',\n    verified:'2026-09-11',\n    cardmarket:{trend:2.04,low:1.33,avg1:1.76,avg7:2.37,avg30:3.39,source:'Cardmarket · Mega Dragonite ex MEP091',sourceUrl:'https://www.cardmarket.com/de/Pokemon/Products/Singles/MEP-Black-Star-Promos/Mega-Dragonite-ex-MEP091',verified:'2026-09-11'}\n  },\n  'MEP 092':{name:'Resort Paradiso',localId:'092',setId:'mep',setName:'Promozioni MEP',category:'Stadio',finish:'',source:'Pokémon ufficiale · MEP 092',sourceUrl:'https://www.pokemon.com/it/play-pokemon/info/entrata-in-vigore-delle-carte-promozionali-del-gcc-pokemon',verified:'2026-09-11'},\n  'MEP 093':{name:'Pikachu',localId:'093',setId:'mep',setName:'Promozioni MEP',category:'Pokemon',finish:'',source:'Pokémon ufficiale · MEP 093',sourceUrl:'https://www.pokemon.com/it/play-pokemon/info/entrata-in-vigore-delle-carte-promozionali-del-gcc-pokemon',verified:'2026-09-11'},\n  'MEP 094':{name:'Exeggutor di Alola',localId:'094',setId:'mep',setName:'Promozioni MEP',category:'Pokemon',finish:'',source:'Pokémon ufficiale · MEP 094',sourceUrl:'https://www.pokemon.com/it/play-pokemon/info/entrata-in-vigore-delle-carte-promozionali-del-gcc-pokemon',verified:'2026-09-11'},\n  'MEP 095':{name:'Lucario',localId:'095',setId:'mep',setName:'Promozioni MEP',category:'Pokemon',finish:'',source:'Pokémon ufficiale · MEP 095',sourceUrl:'https://www.pokemon.com/it/play-pokemon/info/entrata-in-vigore-delle-carte-promozionali-del-gcc-pokemon',verified:'2026-09-11'},\n  'MEP 096':{name:'Moltres',localId:'096',setId:'mep',setName:'Promozioni MEP',category:'Pokemon',finish:'',source:'Pokémon ufficiale · MEP 096',sourceUrl:'https://www.pokemon.com/it/play-pokemon/info/entrata-in-vigore-delle-carte-promozionali-del-gcc-pokemon',verified:'2026-09-11'},\n  'MEP 097':{name:'Articuno',localId:'097',setId:'mep',setName:'Promozioni MEP',category:'Pokemon',finish:'',source:'Pokémon ufficiale · MEP 097',sourceUrl:'https://www.pokemon.com/it/play-pokemon/info/entrata-in-vigore-delle-carte-promozionali-del-gcc-pokemon',verified:'2026-09-11'},\n  'MEP 098':{name:'Zapdos',localId:'098',setId:'mep',setName:'Promozioni MEP',category:'Pokemon',finish:'',source:'Pokémon ufficiale · MEP 098',sourceUrl:'https://www.pokemon.com/it/play-pokemon/info/entrata-in-vigore-delle-carte-promozionali-del-gcc-pokemon',verified:'2026-09-11'},\n  'MEP 099':{name:'Greninja ex',localId:'099',setId:'mep',setName:'Promozioni MEP',category:'Pokemon',finish:'',source:'Pokémon ufficiale · MEP 099',sourceUrl:'https://www.pokemon.com/it/play-pokemon/info/entrata-in-vigore-delle-carte-promozionali-del-gcc-pokemon',verified:'2026-09-11'},\n  'MEP 100':{name:'Sylveon ex',localId:'100',setId:'mep',setName:'Promozioni MEP',category:'Pokemon',finish:'',source:'Pokémon ufficiale · MEP 100',sourceUrl:'https://www.pokemon.com/it/play-pokemon/info/entrata-in-vigore-delle-carte-promozionali-del-gcc-pokemon',verified:'2026-09-11'},\n  'MEP 101':{name:'Nidorina',localId:'101',setId:'mep',setName:'Promozioni MEP',category:'Pokemon',finish:'',source:'Pokémon ufficiale · MEP 101',sourceUrl:'https://www.pokemon.com/it/play-pokemon/info/entrata-in-vigore-delle-carte-promozionali-del-gcc-pokemon',verified:'2026-09-11'}\n};\n"""

if old_registry not in source:
    raise SystemExit('verified promo registry marker missing')
source = source.replace(old_registry, new_registry, 1)

old_return = """  return {\n    id:`verified-promo-${row.setId}-${row.localId}`,\n    tcgdexId:'',name:row.name,localId:row.localId,number:row.localId,\n    category:'Pokemon',rarity:'Promo',variants:{holo:true},\n    variants_detailed:[{type:'holo',languages:['it']}],\n    set:{id:row.setId,name:row.setName},\n    _cardoryxLocal:true,_cardoryxVerifiedPromo:true,_printedCode:key,\n    _verifiedPromoSource:row.source,_verifiedPromoSourceUrl:row.sourceUrl,_verifiedPromoAt:row.verified\n  };\n"""

new_return = """  const finish=String(row.finish||'').trim();\n  const variants=finish==='Holo'?{holo:true}:{};\n  const variantsDetailed=finish==='Holo'?[{type:'holo',languages:['it']}]:[];\n  const cm=row.cardmarket?{\n    trend:row.cardmarket.trend,low:row.cardmarket.low,avg1:row.cardmarket.avg1,avg7:row.cardmarket.avg7,avg30:row.cardmarket.avg30,\n    _cardoryxSource:row.cardmarket.source,_cardoryxSourceUrl:row.cardmarket.sourceUrl,_cardoryxVerified:row.cardmarket.verified\n  }:null;\n  return {\n    id:`verified-promo-${row.setId}-${row.localId}`,\n    tcgdexId:'',name:row.name,localId:row.localId,number:row.localId,\n    category:row.category||'Pokemon',rarity:'Promo',variants,\n    variants_detailed:variantsDetailed,\n    set:{id:row.setId,name:row.setName},\n    ...(cm?{pricing:{cardmarket:cm}}:{}),\n    _cardoryxLocal:true,_cardoryxVerifiedPromo:true,_printedCode:key,\n    _verifiedPromoSource:row.source,_verifiedPromoSourceUrl:row.sourceUrl,_verifiedPromoAt:row.verified\n  };\n"""

if old_return not in source:
    raise SystemExit('verified promo fallback return marker missing')
source = source.replace(old_return, new_return, 1)

index.write_text(source, encoding='utf-8')
print('Official MEP fallbacks prepared')
